import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2021-09-11","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-09-11","date":"2021-09-11T00:00:00.000Z","updated":"2021-09-12T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","BlueStore","IOU Ring"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-09-11.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-09-11.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Performance_Meeting_2021-09-11.md"};function o(n,e,s,h,g,u){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>会议日期</strong>: 2021年9月11日</li><li><strong>参会人员</strong>: 未明确提及</li><li><strong>会议主持</strong>: 未明确提及</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>已合并的PR</strong>:</p><ul><li>Prometheus VR：允许禁用缓存，已合并。</li><li>Omap命名方案限制：Igor提出的PR，用于解决omap列表过大时的内存消耗问题，已合并。</li><li>MDS锁切换：MDS锁切换到公平互斥锁以避免饥饿问题，已合并。</li></ul></li><li><p><strong>更新中的PR</strong>:</p><ul><li>Adam的PR：实现写操作的直接I/O和读操作的缓冲I/O，需审查一致性。</li><li>BlueStore日志增量更新模式：未通过QA测试。</li><li>OSD压缩绕过RGW压缩：已进入Eric的测试分支。</li><li>TTL缓存实现：管理模块的TTL缓存实现，正在进行中。</li><li>优化PG移除PR：Igor的优化PG移除PR，已重新审查。</li><li>Ceph Messenger头2解码优化：已更新，Ilia之前已审查。</li><li>MDS从子树映射移除：从日志中移除MDS从子树映射，Zhang已更新。</li></ul></li><li><p><strong>性能回归分析</strong>:</p><ul><li>OSD代码分析：发现性能回归，主要来源为mclock QoS更改和BlueStore缓冲I/O的默认启用。</li><li>Gabby的PR：移除RocksDB中的分配数据，显著提升了4K随机写性能。</li><li>Adam的PR：讨论直接写和缓冲读的混合模式，可能引入一致性问题。</li></ul></li><li><p><strong>IOU Ring的讨论</strong>:</p><ul><li>IOU Ring的现状：现有代码可能已过时，需要重新评估其在BlueStore中的应用。</li><li>潜在的改进：考虑使用IOU Ring来改善性能，特别是在缓冲I/O模式下。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>性能改进</strong>: 确认Gabby的PR显著提升了性能，解决了之前的性能回归问题。</li><li><strong>IOU Ring的重新评估</strong>: 决定重新评估IOU Ring在Ceph中的应用，特别是在缓冲I/O模式下。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>性能审查</strong>: 对Adam的PR进行仔细审查，确保不会引入一致性问题。</li><li><strong>IOU Ring的评估</strong>: 重新评估和测试IOU Ring的性能和稳定性。</li><li><strong>讨论论文</strong>: 计划在三周后讨论一篇关于Linux内核低延迟优化的论文。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>会议时间调整</strong>: 由于节假日，下次会议时间调整至9月30号。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议讨论了多个PR的进展和性能问题，确认了Gabby的PR对性能的显著提升，并决定重新评估IOU Ring的应用。下次会议将讨论一篇相关论文。</p><h3 id="错误、误解或遗漏的重要信息" tabindex="-1">错误、误解或遗漏的重要信息 <a class="header-anchor" href="#错误、误解或遗漏的重要信息" aria-label="Permalink to &quot;错误、误解或遗漏的重要信息&quot;">​</a></h3><ul><li>原始字幕中提到了一些关于IOU Ring的讨论，但总结中未提及。</li><li>未提及具体参会人员名单和会议主持人。</li></ul><h3 id="改进的中文总结" tabindex="-1">改进的中文总结 <a class="header-anchor" href="#改进的中文总结" aria-label="Permalink to &quot;改进的中文总结&quot;">​</a></h3><p>会议主要讨论了Ceph分布式存储的性能优化议题，包括已合并和更新中的PR、性能回归分析、IOU Ring的讨论以及后续行动计划。会议确认了一些性能提升的方案，并计划对IOU Ring进行重新评估。</p>',17)])])}const p=a(r,[["render",o]]);export{c as __pageData,p as default};
